$keyPtr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($devinSecret)
$pipelineExit = 1
$templatePack = 'C:\Users\User\Downloads\remotion motion graphics templates-20260822T191451Z-1-001.zip'
$editPath = 'C:\Users\User\Downloads\edit'
try {
  $env:DEVIN_API_KEY = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($keyPtr)
  $env:OPENAI_API_KEY = [Environment]::GetEnvironmentVariable('OPENAI_API_KEY', 'User')
  $headers = @{ Authorization = "Bearer $($env:DEVIN_API_KEY)" }
  $sessions = Get-Content -Raw -Encoding utf8 (Join-Path $editPath 'sessions.json') | ConvertFrom-Json
  $cacheDir = Join-Path $editPath 'role-cache'
  New-Item -ItemType Directory -Force -Path $cacheDir | Out-Null
  $resumeRoles = @{
    'A4' = $sessions.A4.url
    'A6' = $sessions.A6.url
    'A6W-solution-step-explainer' = $sessions.'A6.solution-step-explainer'.url
    'A6W-traction-bar-chart-reveal' = $sessions.'A6.traction-bar-chart-reveal'.url
  }
  foreach ($cacheKey in $resumeRoles.Keys) {
    $sessionId = ($resumeRoles[$cacheKey] -split '/')[-1]
    $session = Invoke-RestMethod -Uri "https://api.devin.ai/v1/sessions/$sessionId" -Headers $headers
    if ($null -eq $session.structured_output) { throw "$cacheKey has no structured output" }
    $session.structured_output | ConvertTo-Json -Depth 100 | Set-Content -Encoding utf8 (Join-Path $cacheDir "$cacheKey.json")
  }
  Remove-Item Env:PALANTUM_AGENT_BACKEND -ErrorAction SilentlyContinue
  & '.\.venv\Scripts\palantum.exe' --videos-dir 'C:\Users\User\Downloads' cut --force --resume --template-source $templatePack
  if ($LASTEXITCODE -ne 0) { throw "cut failed with exit code $LASTEXITCODE" }
  & '.\.venv\Scripts\palantum.exe' --videos-dir 'C:\Users\User\Downloads' export
  $pipelineExit = $LASTEXITCODE
} finally {
  [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($keyPtr)
  Remove-Item Env:DEVIN_API_KEY -ErrorAction SilentlyContinue
  Remove-Item Env:OPENAI_API_KEY -ErrorAction SilentlyContinue
}
exit $pipelineExit","workdir":"C:\Users\User\Documents\ChatGPT\cogniframe","yield_time_ms":10000,"max_output_tokens":20000,"tty":true});
